import unittest
from pathlib import Path
import runpy
within = runpy.run_path(str(Path(__file__).resolve().parents[1] / 'clamp.py'))['within']
class Bounds(unittest.TestCase):
    def test_lower_bound(self):
        self.assertTrue(within(0, 0, 3))
    def test_upper_bound(self):
        self.assertTrue(within(3, 0, 3))
